using System.Text.Json.Nodes;
namespace RisingLands;
public static class ResearchV58Tests {
 static void Check(bool yes,string name){if(!yes)throw new Exception("FAIL: v58 "+name);Console.WriteLine("PASS: v58 "+name);}
 public static Simulation Load(string root,int branch=0){var w=LegacyAssets.Map(PackageLayout.Asset(root,"CD/WORLD/MONDE03.ETA"));new VisualCatalog().Apply(w);/* Research timing fixture provisions the army for this long scenario; military hunger is covered separately in v72. */foreach(var a in w.Units.Where(a=>a.Type is 0 or 1 or 2 or 3 or 4 or 8 or 25)){a.Satiety=a.SatietyMaximum=30;}return new(w,new(){StartingLevels=Simulation.UnlockData.Missions.First(m=>m.Mission==3).Levels.ToArray(),SelectedBranch=branch});}
 public static void Advance(Simulation s,int n){for(int i=0;i<n;i++)s.Step();}
 public static int Staff(Simulation s,int count=2){int lab=ResearchTests.PrepareLaboratory(s);for(int n=0;n<count;n++)Check(s.AssignLaboratoryWorker(lab),"assign real researcher");for(int i=0;i<5000&&s.Scientists()<count;i++)s.Step();Check(s.Scientists()==count,"researchers arrive");return lab;}
 public static void GatherFood(Simulation s,int target=50){var farmer=s.World.Units.First(u=>u.Type==5&&u.Owner==0&&VisualCatalog.Visible(u));int depot=s.World.Buildings.First(b=>b.Owner==0&&b.Type==3).Slot;Check(s.SetFoodDestination(farmer,2,depot),"food destination for extra research");for(int i=0;i<60000&&s.World.Resources[0]<target;i++){if(farmer.FoodJob==0)Check(s.GatherNearest(farmer),"collect food for purchase");s.Step();}s.Stop(farmer);Check(s.World.Resources[0]>=target,"actual food collection funds extra research: stock="+s.World.Resources[0]+", cargo="+farmer.Food+", job="+farmer.FoodJob+", hp="+farmer.Health+", satiety="+farmer.Satiety+", consumed="+s.Hunger.Consumed[0]+", warehouse="+s.WarehouseSummary());}
 public static void Run(string root){
  var s=Load(root);int lab=Staff(s,1);Check(s.AgricultureResearch.Enabled&&!s.Research.Enabled,"automatic research follows initial branch");
  int stock=s.World.Resources[0];Check(!s.PurchaseExtraResearch(1)&&s.World.Resources[0]==stock,"cannot buy third before mandatory research");
  Check(!s.ToggleResearch(2)&&s.ActiveResearchBranch==0,"cannot switch branch during mandatory research");
  s.AgricultureResearch.Progress=0;Advance(s,12599);Check(s.MissionResearchCount==0,"one researcher has not finished before seven minutes");s.Step();Check(s.MissionResearchCount==1,"one researcher finishes at exactly seven minutes");
  Check(s.ToggleResearch(0),"manual pause works");double before=s.AgricultureResearch.Progress;Check(s.AssignLaboratoryWorker(lab),"second researcher joins paused lab");Advance(s,2000);Check(s.Scientists()==2&&s.AgricultureResearch.Progress==before&&s.Research.ManualPaused,"arrival never overrides manual pause");
  var copy=Load(root);copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"manual pause survives save load");Check(s.ToggleResearch(0),"resume research");s.AgricultureResearch.Progress=0;
  Advance(s,7199);Check(s.MissionResearchCount==1,"two researchers have not finished before four minutes");s.Step();Check(s.MissionResearchCount==2&&s.ExtraResearchOffered&&s.ResearchPercent==100,"second research finishes at exactly four minutes and offers extra");
  Advance(s,1000);Check(s.MissionResearchCount==2&&s.AgricultureResearch.Progress==0,"mandatory limit does not secretly start third");
  GatherFood(s);int food=s.World.Resources[0];s.World.Resources[0]=49;Check(!s.PurchaseExtraResearch(1)&&s.World.Resources[0]==49,"insufficient food never purchases or spends");s.World.Resources[0]=(ushort)food;
  Check(!s.PurchaseExtraResearch(3)&&s.World.Resources[0]==food,"future spiritual discovery disabled without charge");
  var paidPaused=Load(root);paidPaused.Restore(s.Serialize());paidPaused.Research.ManualPaused=true;Check(paidPaused.PurchaseExtraResearch(0),"extra can choose same branch");Advance(paidPaused,100);Check(paidPaused.AgricultureResearch.Progress==0&&paidPaused.Research.ManualPaused,"paid extra respects preserved manual pause");var paidCopy=Load(root);paidCopy.Restore(paidPaused.Serialize());Check(paidCopy.Serialize()==paidPaused.Serialize(),"paused paid extra saves without food loss");paidPaused.ToggleResearch(0);Advance(paidPaused,7200);paidCopy.Restore(paidPaused.Serialize());Check(paidCopy.MissionResearchCount==3&&paidCopy.ActiveResearchBranch==0,"same branch third discovery completes and saves");
  Check(s.PurchaseExtraResearch(1)&&s.World.Resources[0]==food-50&&s.ActiveResearchBranch==1,"extra choice charges exactly fifty and switches branch");
  Check(!s.PurchaseExtraResearch(2)&&s.World.Resources[0]==food-50,"double purchase rejected");
  string extra=s.Serialize();copy.Restore(extra);Check(copy.Serialize()==extra,"purchase branch and progress roundtrip");
  Advance(s,7199);Advance(copy,7199);Check(s.Serialize()==copy.Serialize()&&s.MissionResearchCount==2,"extra remains timed and deterministic");s.Step();copy.Step();Check(s.MissionResearchCount==3&&s.ResearchPercent==100&&s.Serialize()==copy.Serialize(),"third finishes in four minutes and closes shared quota");
  Check(s.ResearchState(1).Completed.Single()=="MILITAIRE2"&&s.MilitaryDamageBonus(s.World.Units.First(u=>u.Owner==0&&u.Type==0))==1,"military extra applies damage benefit");Advance(s,15000);Check(s.MissionResearchCount==3&&!s.PurchaseExtraResearch(0),"fourth discovery impossible");
  copy.Restore(s.Serialize());Check(copy.Serialize()==s.Serialize(),"finished extra and food spending validate after save");
  var bad=JsonNode.Parse(s.Serialize())!;bad["Research"]!["ExtraBranch"]=2;string unchanged=s.Serialize();try{s.Restore(bad.ToJsonString());throw new Exception("Invalid extra accepted");}catch(InvalidDataException){}Check(s.Serialize()==unchanged,"invalid extra branch rejected atomically");
  var mixed=Load(root);int ml=Staff(mixed,1);mixed.AgricultureResearch.Progress=0;Advance(mixed,6300);Check(Math.Abs(mixed.AgricultureResearch.Progress/mixed.ResearchInvention(0)!.Cost-.5)<1e-8,"half complete after three and half minutes with one");mixed.ToggleResearch(0);mixed.AssignLaboratoryWorker(ml);Advance(mixed,2000);mixed.ToggleResearch(0);Advance(mixed,3599);Check(mixed.MissionResearchCount==0,"adding second preserves work and requires remaining two minutes");mixed.Step();Check(mixed.MissionResearchCount==1,"mixed researcher schedule completes without resetting");
  string pause=mixed.Serialize();var old=JsonNode.Parse(pause)!;old["Version"]=22;old["Research"]!.AsObject().Remove("Military");old["Research"]!.AsObject().Remove("Spiritual");copy.Restore(old.ToJsonString());Check(copy.MissionResearchCount==mixed.MissionResearchCount&&copy.ActiveResearchBranch==0,"old v22 migration preserves discoveries and initial branch");
  Check(mixed.ReturnLaboratoryWorker(ml)&&mixed.ReturnLaboratoryWorker(ml)&&mixed.Scientists()==0,"all researchers can leave through existing commands");double held=mixed.AgricultureResearch.Progress;Advance(mixed,3000);Check(mixed.AgricultureResearch.Progress==held&&!mixed.Research.ManualPaused&&mixed.ResearchStatus(0)=="Sem colonos no laboratorio","empty laboratory suspends without converting to manual pause");Check(mixed.AssignLaboratoryWorker(ml),"researcher can return after absence");Advance(mixed,3000);Check(mixed.AgricultureResearch.Progress>held&&mixed.AgricultureResearch.Enabled,"research resumes automatically after absence");
  var engineering=Load(root,2);Staff(engineering);engineering.Research.Progress=0;Advance(engineering,14400);Check(engineering.MissionResearchCount==2&&engineering.ExtraResearchOffered&&engineering.ConstructionStrikeProgress==2,"engineering mandatory discoveries preserve native hammer strength");GatherFood(engineering);Check(engineering.PurchaseExtraResearch(2),"engineering extra unlocks available construction improvement");Advance(engineering,7200);Check(engineering.MissionResearchCount==3&&engineering.ConstructionStrikeProgress==3,"construction extra adds fifty percent work per hammer strike");var engineeringCopy=Load(root,2);engineeringCopy.Restore(engineering.Serialize());Check(engineeringCopy.ConstructionStrikeProgress==3,"construction extra survives save and load");
  Console.WriteLine("ALL V58 RESEARCH TESTS PASSED");
 }
}
